// Hand-written. Not generated by Speakeasy.
//
// Deciding that a resource is gone is the most destructive judgement this
// provider makes. Terraform's answer to "gone" is to drop it from state and
// plan a replacement, so a wrong answer creates a second service or client
// and orphans the original, which keeps running and keeps issuing tokens.
//
// The generated code answered it with the status code alone: any 404 was
// gone, and Delete treated any 404 as success. That is wrong twice over.
//
// A 404 is not proof. An nginx error page, a proxy, a maintenance page or a
// typo in server_url all return one, usually with an HTML body. Pointing
// server_url at a host that does not serve Authlete made every resource plan
// for recreation.
//
// And Authlete does not use 404 consistently anyway:
//
//	service read, server      403 with resultCode A458203, never 404
//	service delete, IdP       404 with "Service is not found"
//	client read and delete    404 with resultCode A001212 or A001214
//
// So the body decides, not the status, and a response that does not say one
// of those things is reported rather than acted on.
//
// The second judgement is where. A service id is unique to the cluster that
// issued it, and deletion is a hard delete, so a cluster that never had the
// service answers exactly as one that has deleted it. A CI pipeline pointed
// at the wrong AUTHLETE_SERVER_URL would therefore recreate every service it
// manages. The host that last answered successfully is remembered in private
// state, and a "gone" from anywhere else is refused.
//
// The call sites are in generated files, so scripts/patch-missing-service.py
// reapplies them after regeneration and --check guards them in CI.
package provider

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"

	"github.com/authlete/terraform-provider-authlete/v3/internal/sdk/models/operations"
	"github.com/hashicorp/terraform-plugin-framework/diag"
)

// The markers that mean the object is not there. Everything else, at any
// status, is an unexpected response.
const (
	// Inside a 403, from the server, when the service in the path does not
	// exist. Both a deleted id and an id that never existed return it.
	serviceNotFoundCode = "A458203"

	// Inside a 404, from the IdP, when removing a service it cannot find.
	// The IdP looks the service up before it checks the token, so an unknown
	// organization or api server reaches this too, which is why the host
	// check below matters.
	serviceRemoveNotFound = "Service is not found"
)

// clientNotFoundCodes are the resultCodes Authlete returns, inside a 404, for
// a client that does not exist.
var clientNotFoundCodes = []string{"A001212", "A001214"}

// hostKey is where the host that last answered for this resource is kept.
const hostKey = "authlete_host"

// body returns the response body without consuming it for later callers.
func body(res *http.Response) []byte {
	if res == nil {
		return nil
	}
	// What the transport kept, if it saw this response. The SDK calls
	// DrainBody on a 404, which is exactly the Delete path, so by the time
	// anything here looks there is nothing left to read. See captured_body.go.
	if raw := capturedBody(res); raw != nil {
		return raw
	}
	if res.Body == nil {
		return nil
	}
	raw, err := io.ReadAll(io.LimitReader(res.Body, maxCapturedBody))
	res.Body.Close()
	res.Body = io.NopCloser(bytes.NewReader(raw))
	if err != nil {
		return nil
	}
	return raw
}

// Only exact fields in an Authlete JSON error identify a deletion. A marker
// mentioned in an HTML page, a different error's message, or a longer code
// is not proof that the resource is gone.
func deletionProblem(res *http.Response) (code, message string) {
	var problem struct {
		ResultCode string `json:"resultCode"`
		Error      string `json:"error"`
	}
	if err := json.Unmarshal(body(res), &problem); err != nil {
		return "", ""
	}
	return problem.ResultCode, problem.Error
}

// serviceIsGone reports whether a response says this service does not exist,
// as opposed to the caller not being allowed to see it, or the host not
// serving Authlete at all.
func serviceIsGone(res *http.Response) bool {
	if res == nil {
		return false
	}
	code, message := deletionProblem(res)
	switch res.StatusCode {
	case http.StatusForbidden:
		return code == serviceNotFoundCode
	case http.StatusNotFound:
		// Only the IdP's remove endpoint answers this way.
		return message == serviceRemoveNotFound
	}
	return false
}

// clientIsGone reports whether a response says this client does not exist. A
// 404 alone is not enough: the generated code used to accept any of them.
func clientIsGone(res *http.Response) bool {
	if res == nil || res.StatusCode != http.StatusNotFound {
		return false
	}
	resultCode, _ := deletionProblem(res)
	for _, code := range clientNotFoundCodes {
		if resultCode == code {
			return true
		}
	}
	return false
}

// clientOrServiceIsGone covers a client. A client path carries the service
// id, so a client whose service was deleted answers with the service's 403
// rather than the client's 404: the clients went with the service.
func clientOrServiceIsGone(res *http.Response) bool {
	return clientIsGone(res) || serviceIsGone(res)
}

// responseHost describes where a resource lives: the configured server_url
// together with the IdP coordinates, not whichever host happened to answer.
// Creating or deleting a service is answered by the IdP while the service
// itself lives on server_url, so the two differ exactly where getting it
// wrong is most expensive. See captured_body.go.
func responseHost(res *http.Response) string {
	return locationOf(res).Describe()
}

// rememberHost records where a resource lives, so a later "gone" can be
// checked against it. Called from Create as well as Read: a resource created
// and then looked for somewhere else, with no refresh in between, was
// unprotected while this ran on Read alone, and a plan does not save state.
func rememberHost(ctx context.Context, p interface {
	SetKey(context.Context, string, []byte) diag.Diagnostics
}, res *http.Response) {
	where := locationOf(res)
	if where.Host == "" || p == nil {
		return
	}
	raw, err := json.Marshal(where)
	if err != nil {
		return
	}
	// A failure to record only costs the check below, so it is not reported.
	_ = p.SetKey(ctx, hostKey, raw)
}

// movedHost returns a description of the recorded location when it differs
// from the one that just answered. An empty result means there is nothing to
// object to: either nothing was recorded, or it is the same place.
func movedHost(ctx context.Context, p interface {
	GetKey(context.Context, string) ([]byte, diag.Diagnostics)
}, res *http.Response) string {
	if p == nil {
		return ""
	}
	raw, diags := p.GetKey(ctx, hostKey)
	if diags.HasError() || len(raw) == 0 {
		return ""
	}
	was, legacy, ok := decodeLocation(raw)
	if !ok || was.Host == "" {
		return ""
	}
	now := locationOf(res)
	if legacy {
		// All an older record holds is the cluster, so that is all it can be
		// compared on. Comparing the rest would read every upgraded resource
		// as having moved and refuse every genuine deletion.
		if was.Host == now.Host {
			return ""
		}
		return was.Describe()
	}
	if len(was.Differences(now)) == 0 {
		return ""
	}
	return was.Describe()
}

// decodeLocation reads what rememberHost wrote. State written before the IdP
// coordinates were recorded holds a bare host string, and must keep working:
// treating it as unreadable would be harmless, but treating it as a mismatch
// would refuse every genuine deletion after an upgrade.
// The second return reports whether the record is the older host-only form,
// which can only be compared on the cluster.
func decodeLocation(raw []byte) (where Location, legacy, ok bool) {
	var host string
	if err := json.Unmarshal(raw, &host); err == nil && host != "" {
		return Location{Host: host}, true, true
	}
	if err := json.Unmarshal(raw, &where); err == nil && where.Host != "" {
		return where, false, true
	}
	return Location{}, false, false
}

// goneElsewhereMessage is raised instead of dropping, or silently not
// deleting, a resource that is missing from somewhere other than where it was
// last seen. Recreating would leave the original running and unmanaged;
// reporting a successful destroy would do the same.
func goneElsewhereMessage(was, now string) (summary, detail string) {
	return "Resource not found in the configured location",
		fmt.Sprintf("This resource was last seen at %s, and %s reports that it "+
			"does not exist.\n\n"+
			"A service id is unique to the cluster that issued it, and the "+
			"identity server looks a service up under an organization on an api "+
			"server. A place that never had the service answers exactly as one "+
			"that has deleted it, so Terraform cannot tell the two apart and "+
			"will not assume the resource is gone.\n\n"+
			"If server_url, idp_host, organization_id or api_server_id changed "+
			"by mistake, put the old value back. If the move was intended, "+
			"remove the resource from state and import it where it now lives.",
			was, now)
}

// serviceGoneMessage is the diagnostic a data source raises instead of
// reporting a bare 403. A data source cannot drop itself from state the way a
// resource can, since it was never in state; the right outcome is an error, so
// what matters here is that the error says what is wrong.
//
// The summary names the service, because a configuration that reads several
// has no other way to tell which one is missing.
func serviceGoneMessage(id string) (summary, detail string) {
	return fmt.Sprintf("Service %s does not exist", id),
		"Authlete reports no service with this id.\n\n" +
			"It may have been deleted, or the id may belong to another " +
			"organization or another cluster: a service id is unique to the " +
			"cluster that issued it, so one created on us.authlete.com is not " +
			"found on jp.authlete.com.\n\n" +
			"Check the id against the Management Console, and check that " +
			"server_url and AUTHLETE_SERVER_URL name the cluster the service " +
			"lives on."
}

// The record alone cannot answer "is this service really gone".
//
// The place a resource lives is written from the configuration on every
// successful read, and a read goes to server_url, which ignores
// organization_id, idp_host and api_server_id. So a run with the wrong
// organization reads successfully, overwrites the record with the wrong
// organization, and the IdP's "Service is not found" then agrees with the
// record it just wrote. Destroy reported success and the service kept
// running. Only the host component is ever proved by anything.
//
// So for a service the IdP says is missing, ask the cluster, which does know.
// A service id is resolved there without reference to any of the three IdP
// coordinates, so a 200 means the service exists and the IdP's answer was
// about the coordinates, not about the service.
type serviceReader interface {
	ServiceGetAPI(context.Context, operations.ServiceGetAPIRequest, ...operations.Option) (*operations.ServiceGetAPIResponse, error)
}

// serviceStillExists asks the cluster directly. The second return reports
// whether the question could be answered at all: a transport failure or an
// unexpected status is not evidence either way, and must not be read as
// permission to drop the resource.
func serviceStillExists(ctx context.Context, api serviceReader, serviceID int64) (exists, known bool) {
	if api == nil {
		return false, false
	}
	res, err := api.ServiceGetAPI(ctx, operations.ServiceGetAPIRequest{ServiceID: serviceID})
	if err != nil || res == nil || res.RawResponse == nil {
		return false, false
	}
	if res.RawResponse.StatusCode == http.StatusOK {
		return true, true
	}
	if serviceIsGone(res.RawResponse) {
		return false, true
	}
	return false, false
}

// serviceStillThereMessage is raised when the identity server says a service
// is missing but the cluster still has it. The usual cause is that one of the
// three coordinates the identity server resolves by is wrong.
func serviceStillThereMessage(id string, where Location) (summary, detail string) {
	return "Service still exists, so it was not deleted",
		fmt.Sprintf("The identity server reports that service %s does not exist, but %s still "+
			"returns it.\n\n"+
			"The identity server finds a service through organization_id, api_server_id and "+
			"idp_host. When any of those names a different place, it answers exactly as it "+
			"would for a service that had been deleted. Terraform will not drop a resource "+
			"that is demonstrably still there.\n\n"+
			"Check organization_id, api_server_id and idp_host against the service in the "+
			"Management Console. The configuration currently names %s.", id, where.Host, where.Describe())
}

// noRecordMessage is raised when a resource is reported missing and nothing
// was ever recorded about where it lives.
//
// State written before this provider recorded a location, which is every
// service created by 3.0.0-beta3 and everything upgraded from 1.3.x, carries
// no record. Treating "nothing recorded" as "nothing to object to" meant the
// first run after an upgrade had no protection at all, so a mistyped
// server_url in CI dropped the resource and created a duplicate. That is the
// run where a mistyped server_url is most likely.
func noRecordMessage(what, id string) (summary, detail string) {
	return fmt.Sprintf("Cannot confirm that %s %s is gone", what, id),
		"This resource is reported as missing, and Terraform has no record of where it " +
			"was last seen, so it cannot tell a deletion apart from a configuration that " +
			"points somewhere else.\n\n" +
			"State written before this version, including state upgraded from 1.3.x, " +
			"carries no such record. The first run with this provider establishes one.\n\n" +
			"If server_url, idp_host, organization_id and api_server_id are correct, run " +
			"terraform apply -refresh-only to record the location, after which this " +
			"resource is protected and a genuine deletion is handled normally.\n\n" +
			"If the resource really was deleted outside Terraform, remove it from state " +
			"with terraform state rm and apply again to recreate it."
}

// hasRecord reports whether anything is recorded about where this resource
// lives.
func hasRecord(ctx context.Context, p interface {
	GetKey(context.Context, string) ([]byte, diag.Diagnostics)
}) bool {
	if p == nil {
		return false
	}
	raw, diags := p.GetKey(ctx, hostKey)
	if diags.HasError() || len(raw) == 0 {
		return false
	}
	_, _, ok := decodeLocation(raw)
	return ok
}

// privateReader is the part of private state these decisions need.
type privateReader interface {
	GetKey(context.Context, string) ([]byte, diag.Diagnostics)
}

// mayTreatAsGone is the single decision behind every "drop this resource" in
// the provider. Read and Delete, service and client, all come here.
//
// It lives in one place because the same bug was found in three reviews, each
// time at one call site that had been given a check the others had not. The
// last of them was service Delete, the only path with no check that anything
// had ever been recorded.
//
// confirm is optional, and is the only independent evidence available. It is
// supplied for a service Delete, where the identity server's answer depends
// on coordinates the cluster does not use. It is not supplied where the
// answer already came from the cluster, since asking the same host twice
// proves nothing. Note that it cannot stand in for the record check either:
// it reaches the host in the current configuration, so a wrong server_url is
// confirmed by the wrong cluster.
func mayTreatAsGone(
	ctx context.Context,
	p privateReader,
	res *http.Response,
	what, id string,
	confirm func() (exists, known bool),
) (gone bool, summary, detail string) {
	// Somewhere other than where it was last seen cannot report it missing.
	if was := movedHost(ctx, p, res); was != "" {
		s, d := goneElsewhereMessage(was, responseHost(res))
		return false, s, d
	}
	// Nothing was ever recorded, so there is nothing to check the answer
	// against. State from 3.0.0-beta3 and from 1.3.x arrives this way, and
	// the first run is when a mistyped server_url is most likely.
	if !hasRecord(ctx, p) {
		s, d := noRecordMessage(what, id)
		return false, s, d
	}
	if confirm != nil {
		if exists, known := confirm(); exists || !known {
			s, d := serviceStillThereMessage(id, locationOf(res))
			return false, s, d
		}
	}
	return true, "", ""
}
